const fs = require('fs');

function solve() {
    const input = fs.readFileSync(0, 'utf-8');
    let pos = 0;

    function nextToken() {
        while (pos < input.length && input.charCodeAt(pos) <= 32) {
            pos++;
        }
        if (pos >= input.length) return null;
        const start = pos;
        while (pos < input.length && input.charCodeAt(pos) > 32) {
            pos++;
        }
        return input.slice(start, pos);
    }

    const nStr = nextToken();
    if (!nStr) return;
    const n = parseInt(nStr, 10);

    const prefixes = new Set();
    const suffixes = new Set();
    const substrings = new Set();

    for (let k = 0; k < n; k++) {
        const s = nextToken();
        if (!s) break;
        const len = s.length;

        // Para k > 0, checa se s pode ser formada por strings anteriores
        if (k > 0) {
            let invalid = false;

            // Caso 1: s é substring de alguma string anterior
            if (substrings.has(s)) {
                invalid = true;
            }

            // Caso 2: s é formada por um sufixo de S_a e um prefixo de S_b
            if (!invalid) {
                for (let i = 1; i < len; i++) {
                    const left = s.slice(0, i);
                    const right = s.slice(i);
                    if (suffixes.has(left) && prefixes.has(right)) {
                        invalid = true;
                        break;
                    }
                }
            }

            if (invalid) {
                console.log(s);
                return;
            }
        }

        // Adiciona prefixos, sufixos e substrings de s aos conjuntos
        for (let i = 1; i <= len; i++) {
            prefixes.add(s.slice(0, i));
            suffixes.add(s.slice(len - i));
        }

        for (let i = 0; i < len; i++) {
            for (let j = i + 1; j <= len; j++) {
                substrings.add(s.slice(i, j));
            }
        }
    }

    console.log('ok');
}

solve();
